INSERT INTO books (title, author, isbn, category_id, price, stock, description, cover_image, publisher, pub_year, pages, rating) VALUES ('Pride and Prejudice', 'Jane Austen', '978-81-9007-13-1', (SELECT category_id FROM categories WHERE name = 'Classics'), 299, 40, 'Elizabeth Bennet trades sharp words with the proud Mr Darcy in a witty study of manners, marriage and first impressions in Regency England.', 'book-01.svg', 'Penguin Classics', 1813, 432, 4.7);
INSERT INTO books (title, author, isbn, category_id, price, stock, description, cover_image, publisher, pub_year, pages, rating) VALUES ('1984', 'George Orwell', '978-81-9014-26-2', (SELECT category_id FROM categories WHERE name = 'Classics'), 349, 55, 'Winston Smith quietly rebels against a regime that watches every move and rewrites every truth. A chilling classic about surveillance and freedom.', 'book-02.svg', 'Penguin Modern', 1949, 328, 4.8);
INSERT INTO books (title, author, isbn, category_id, price, stock, description, cover_image, publisher, pub_year, pages, rating) VALUES ('To Kill a Mockingbird', 'Harper Lee', '978-81-9021-39-3', (SELECT category_id FROM categories WHERE name = 'Classics'), 399, 30, 'Through the eyes of young Scout Finch, a small Alabama town is tested when her father defends a Black man accused of a crime he did not commit.', 'book-03.svg', 'Harper Perennial', 1960, 336, 4.8);
